normal=normalize(vec3(sin(w.x*1.8+w.y*.7+time*1.2)*.075+sin(w.y*4.-time*1.6)*(.025+riffle*.09),1.,cos(w.y*1.6+w.x*.5-time*.8)*(.08+riffle*.12)));
